function maximumUniqueSubarray(nums) {
  const seen = new Set();
  let left = 0;
  let windowSum = 0;
  let best = 0;

  for (let right = 0; right < nums.length; right++) {
    while (seen.has(nums[right])) {
      seen.delete(nums[left]);
      windowSum -= nums[left];
      left++;
    }
    seen.add(nums[right]);
    windowSum += nums[right];
    best = Math.max(best, windowSum);
  }
  return best;
}

