function maximumUniqueSubarray(nums) {
  let best = 0;
  for (let start = 0; start < nums.length; start++) {
    const used = [];
    let total = 0;
    for (let end = start; end < nums.length; end++) {
      if (used.includes(nums[end])) break;
      used.push(nums[end]);
      total += nums[end];
      if (total > best) best = total;
    }
  }
  return best;
}

