function generate(rand, size) {
  if (size === 'large') {
    const spans = [50, 600, 10000];
    const span = spans[Math.floor(rand() * spans.length)];
    return [Array.from({ length: 2000 }, () => 1 + Math.floor(rand() * span))];
  }
  const n = 1 + Math.floor(rand() * 10);
  const span = 1 + Math.floor(rand() * 6);
  const big = rand() < 0.3;
  return [Array.from({ length: n }, () => (big ? 10000 - span : 0) + 1 + Math.floor(rand() * span))];
}
